  1	import java.util.Arrays;
  2	import java.util.Objects;
  3	
  4	public final class BucketSort {
  5	
  6	    private static final float MIN_SUPPORTED_VALUE = 0.0f;
  7	    private static final float MAX_SUPPORTED_VALUE = 1.0f;
  8	
  9	    private BucketSort() {
 10	    }
 11	
 12	    public static void sort(float[] values) {
 13	        Objects.requireNonNull(values, "values");
 14	        sortInPlace(values);
 15	    }
 16	
 17	    public static float[] sortedCopy(float[] values) {
 18	        Objects.requireNonNull(values, "values");
 19	
 20	        float[] copy = Arrays.copyOf(values, values.length);
 21	        sortInPlace(copy);
 22	        return copy;
 23	    }
 24	
 25	    private static void sortInPlace(float[] values) {
 26	        if (values.length == 0) {
 27	            return;
 28	        }
 29	
 30	        BucketSet buckets = new BucketSet(values.length);
 31	        distribute(values, buckets);
 32	        buckets.sortEach();
 33	        buckets.writeBack(values);
 34	    }
 35	
 36	    private static void distribute(float[] values, BucketSet buckets) {
 37	        for (float value : values) {
 38	            validateValue(value);
 39	            buckets.add(value);
 40	        }
 41	    }
 42	
 43	    private static void insertionSort(float[] bucket, int size) {
 44	        for (int i = 1; i < size; i++) {
 45	            float currentValue = bucket[i];
 46	            int j = i - 1;
 47	            while (j >= 0 && bucket[j] > currentValue) {
 48	                bucket[j + 1] = bucket[j];
 49	                j--;
 50	            }
 51	            bucket[j + 1] = currentValue;
 52	        }
 53	    }
 54	
 55	    private static int bucketIndexFor(float value, int bucketCount) {
 56	        return (int) (bucketCount * value);
 57	    }
 58	
 59	    private static void validateValue(float value) {
 60	        if (value < MIN_SUPPORTED_VALUE || value >= MAX_SUPPORTED_VALUE) {
 61	            throw new IllegalArgumentException(
 62	                "Bucket sort expects values in the range ["
 63	                    + MIN_SUPPORTED_VALUE
 64	                    + ", "
 65	                    + MAX_SUPPORTED_VALUE
 66	                    + "): "
 67	                    + value
 68	            );
 69	        }
 70	    }
 71	
 72	    private static final class BucketSet {
 73	
 74	        private final Bucket[] buckets;
 75	
 76	        private BucketSet(int bucketCount) {
 77	            buckets = new Bucket[bucketCount];
 78	
 79	            for (int i = 0; i < bucketCount; i++) {
 80	                buckets[i] = new Bucket();
 81	            }
 82	        }
 83	
 84	        private void sortEach() {
 85	            for (Bucket bucket : buckets) {
 86	                bucket.sort();
 87	            }
 88	        }
 89	
 90	        private void writeBack(float[] target) {
 91	            int targetIndex = 0;
 92	            for (Bucket bucket : buckets) {
 93	                targetIndex = bucket.writeTo(target, targetIndex);
 94	            }
 95	        }
 96	
 97	        private void add(float value) {
 98	            int bucketIndex = bucketIndexFor(value, buckets.length);
 99	            buckets[bucketIndex].add(value);
100	        }
101	    }
102	
103	    private static final class Bucket {
104	
105	        private float[] values = new float[0];
106	        private int size;
107	
108	        private void add(float value) {
109	            ensureCapacity(size + 1);
110	            values[size] = value;
111	            size++;
112	        }
113	
114	        private void sort() {
115	            insertionSort(values, size);
116	        }
117	
118	        private int writeTo(float[] target, int targetIndex) {
119	            System.arraycopy(values, 0, target, targetIndex, size);
120	            return targetIndex + size;
121	        }
122	
123	        private void ensureCapacity(int minCapacity) {
124	            if (values.length >= minCapacity) {
125	                return;
126	            }
127	
128	            int newCapacity = Math.max(1, values.length * 2);
129	            while (newCapacity < minCapacity) {
130	                newCapacity *= 2;
131	            }
132	            values = Arrays.copyOf(values, newCapacity);
133	        }
134	    }
135	}

  1	import java.util.Arrays;
  2	
  3	public final class BucketSortTest {
  4	
  5	    private BucketSortTest() {
  6	    }
  7	
  8	    public static void main(String[] args) {
  9	        sortsValuesInPlace();
 10	        returnsSortedCopyWithoutMutatingInput();
 11	        returnsDistinctArrayForSortedCopy();
 12	        sortsDuplicateValues();
 13	        sortsValuesNearUpperBound();
 14	        rejectsOutOfRangeValues();
 15	        rejectsNullInput();
 16	        handlesEmptyInput();
 17	        returnsEmptySortedCopy();
 18	    }
 19	
 20	    private static void sortsValuesInPlace() {
 21	        float[] values = {0.42f, 0.32f, 0.23f, 0.52f, 0.25f, 0.47f};
 22	        BucketSort.sort(values);
 23	
 24	        assertArrayEquals(
 25	            new float[]{0.23f, 0.25f, 0.32f, 0.42f, 0.47f, 0.52f},
 26	            values,
 27	            "sort should order values in place"
 28	        );
 29	    }
 30	
 31	    private static void returnsSortedCopyWithoutMutatingInput() {
 32	        float[] original = {0.78f, 0.17f, 0.39f};
 33	        float[] copy = BucketSort.sortedCopy(original);
 34	
 35	        assertArrayEquals(
 36	            new float[]{0.78f, 0.17f, 0.39f},
 37	            original,
 38	            "sortedCopy should not mutate the source array"
 39	        );
 40	        assertArrayEquals(
 41	            new float[]{0.17f, 0.39f, 0.78f},
 42	            copy,
 43	            "sortedCopy should return sorted data"
 44	        );
 45	    }
 46	
 47	    private static void returnsDistinctArrayForSortedCopy() {
 48	        float[] original = {0.31f, 0.21f};
 49	        float[] copy = BucketSort.sortedCopy(original);
 50	
 51	        if (copy == original) {
 52	            throw new AssertionError("sortedCopy should return a distinct array instance");
 53	        }
 54	    }
 55	
 56	    private static void sortsDuplicateValues() {
 57	        float[] values = {0.41f, 0.12f, 0.41f, 0.12f, 0.73f};
 58	        BucketSort.sort(values);
 59	
 60	        assertArrayEquals(
 61	            new float[]{0.12f, 0.12f, 0.41f, 0.41f, 0.73f},
 62	            values,
 63	            "sort should handle duplicate values"
 64	        );
 65	    }
 66	
 67	    private static void sortsValuesNearUpperBound() {
 68	        float[] values = {0.9999f, 0.0001f, 0.5f};
 69	        BucketSort.sort(values);
 70	
 71	        assertArrayEquals(
 72	            new float[]{0.0001f, 0.5f, 0.9999f},
 73	            values,
 74	            "sort should support values close to the upper bound"
 75	        );
 76	    }
 77	
 78	    private static void rejectsOutOfRangeValues() {
 79	        assertThrows(
 80	            IllegalArgumentException.class,
 81	            () -> BucketSort.sort(new float[]{0.5f, 1.0f}),
 82	            "sort should reject values outside [0.0, 1.0)"
 83	        );
 84	    }
 85	
 86	    private static void rejectsNullInput() {
 87	        assertThrows(
 88	            NullPointerException.class,
 89	            () -> BucketSort.sort(null),
 90	            "sort should reject null input"
 91	        );
 92	    }
 93	
 94	    private static void handlesEmptyInput() {
 95	        float[] values = {};
 96	        BucketSort.sort(values);
 97	        assertArrayEquals(new float[]{}, values, "sort should leave empty input unchanged");
 98	    }
 99	
100	    private static void returnsEmptySortedCopy() {
101	        float[] copy = BucketSort.sortedCopy(new float[]{});
102	        assertArrayEquals(new float[]{}, copy, "sortedCopy should handle empty input");
103	    }
104	
105	    private static void assertArrayEquals(float[] expected, float[] actual, String message) {
106	        if (!Arrays.equals(expected, actual)) {
107	            throw new AssertionError(
108	                message
109	                    + ". Expected "
110	                    + Arrays.toString(expected)
111	                    + " but was "
112	                    + Arrays.toString(actual)
113	            );
114	        }
115	    }
116	
117	    private static void assertThrows(
118	        Class<? extends Throwable> expectedType,
119	        ThrowingRunnable runnable,
120	        String message
121	    ) {
122	        try {
123	            runnable.run();
124	        } catch (Throwable error) {
125	            if (expectedType.isInstance(error)) {
126	                return;
127	            }
128	            throw new AssertionError(
129	                message + ". Expected " + expectedType.getSimpleName() + " but caught " + error,
130	                error
131	            );
132	        }
133	
134	        throw new AssertionError(
135	            message + ". Expected " + expectedType.getSimpleName() + " but nothing was thrown"
136	        );
137	    }
138	
139	    @FunctionalInterface
140	    private interface ThrowingRunnable {
141	        void run();
142	    }
143	}
